SELECT L.ID, COALESCE(LC.TITULO, L.TITULO) TITULO, COALESCE(LC.AUTOR, L.AUTOR) AUTOR, L.TRECHO, L.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(COALESCE(LC.TITULO, L.TITULO), ' ', COALESCE(LC.AUTOR, L.AUTOR, ''), ' ', COALESCE(L.TRECHO, '')) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) ORDER BY COALESCE(LC.TITULO, L.TITULO), V.PUBLICADO_EM DESC, L.ID LIMIT {{limit}} OFFSET {{offset}}